for cap in (7,8,9,10):
    fm=Counter(); acc=Counter(); N=Counter(); use=0
    for seed in range(10):
        rng=random.Random(seed)
        for q in qs:
            pools={v:list(q['pools'][v]) for v in range(5)}
            for p in pools.values(): rng.shuffle(p)
            samples=[]; v=0
