                if len(samples)>=5:
                    b,(_,n,nv,mean),mg=m._best_and_margin(samples)
                    if m._stop(n,nv,mean,len(samples)): break
                p=pools[v%5]
                if not p: break
                a,s=p.pop(); samples.append((v%5,a,s)); v+=1
            use+=len(samples)
            b,(_,n,nv,mean),mg=m._best_and_margin(samples)
            ok=b==q['correct']; acc[q['topic']]+=ok; N[q['topic']]+=1
            if not ok:
                sc=m._score_answers(samples)
                if q['correct'] not in sc: fm[(q['topic'],'correct_never_sampled',len(samples))]+=1
                else:
                    cn=sc[q['correct']][1]; cnv=sc[q['correct']][2]
                    fm[(q['topic'],f'lost c_n={cn} c_nv={cnv} b_n={n} b_nv={nv} bmean={mean:.1f} cmean={sc[q["correct"]][3]:.1f}')]+=1
